#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

int route(const int&) { return 1; } int route(int&&) { return 2; }
int solve(int a, int b) { int&& ref = std::move(a); return 10 * route(ref) + route(std::move(b)); }
